} else {
    long long v = (long long)(*FUZZ_PARAM(long long));
    auto u = nonstd::make_unexpected(v);
    (void)u;
}
// Validation: No API error paths; ensures factory accepts multiple E forms and constructs successfully.

// Exercise both swap overload patterns where possible.
// 1) swap(unexpected_type<E>&, unexpected_type<E>&)
{
    int a = (int)(*FUZZ_PARAM(int));
    int b = (int)(*FUZZ_PARAM(int));
    auto ux = nonstd::expected_lite::make_unexpected(a);
    auto uy = nonstd::expected_lite::make_unexpected(b);
    nonstd::expected_lite::swap(ux, uy);
    // also touch member swap(y) along the noexcept path via ADL constraints
    ux.swap(uy);
}
// 2) swap(expected<T,E>&, expected<T,E>&) where T,E are swappable & move-constructible
{
    using T = int;
    using E = int;
    // Construct one expected with value, one with error; then swap states
    T v = (T)(*FUZZ_PARAM(int));
    E e = (E)(*FUZZ_PARAM(int));
    nonstd::expected_lite::expected<T,E> x(v);
    auto une = nonstd::expected_lite::make_unexpected(e);
    nonstd::expected_lite::expected<T,E> y(une);
    nonstd::expected_lite::swap(x, y);
    // swap back via member to traverse both code paths
    x.swap(y);
}
// Validation: Chooses simple integral T/E to satisfy enable_if constraints; no persistent objects or error paths.

